func:
// =====================================================================
// A07 · MODELO FÍSICO DE LA LÍNEA DE EMBOTELLADO (gemelo digital)
// Entrada 1: msg.topic = "tick"  -> avanza el modelo según el tiempo real
// Entrada 2: msg.topic = "cmd"   -> aplica un comando YA VALIDADO por la
//                                  lógica de control (pestaña 2)
// Salida 1: instantánea del estado (cada tick)
// Salida 2: resultado de ejecución de un comando (para el /ack)
// El estado vive SOLO en el contexto de este nodo (no se usan globales).
// =====================================================================

// ---------- Parámetros (valores didácticos de referencia) ----------
const P = {
    NOMINAL: 24,          // envases/min  capacidad nominal de la línea
    SP_MIN: 6,            // envases/min  consigna mínima
    SP_MAX: 30,           // envases/min  consigna máxima admitida
    ACC: 6,               // (envases/min)/s  rampa máxima del motor
    TRANSFER: 0.25,       // fracción del ciclo usada para transferir envases
    VB: 500,              // mL  volumen nominal del envase
    Q_NOM: 300,           // mL/s caudal nominal de la válvula de llenado
    TARGET: 95,           // %   llenado objetivo
    TOL: 2,               // %   tolerancia de inspección (±)
    CLOSE_SD: 0.4,        // %   dispersión del cierre de válvula
    FILL_FAULT: 0.70,     // factor de caudal con boquilla obstruida
    Q_TAU: 8,             // s   constante de tiempo de la perturbación de caudal
    Q_SD: 0.03,           // -   desviación típica relativa de la perturbación
    BUF_MAX: 30,          // envases  capacidad de la mesa de alimentación
    SUPPLY: 28,           // envases/min  aporte del despaletizador
    GAP_PROB: 0.01,       // 1/s probabilidad de micro-parada del despaletizador
    GAP_MIN: 2, GAP_MAX: 6, // s duración de la micro-parada
    CAP_MAX: 20,          // tapas  capacidad de la tolva
    CAP_FEED: 30,         // tapas/min  alimentador de tapas
    T_CAP: 0.5,           // s  tiempo de roscado
    T_LABEL: 0.8,         // s  tiempo de etiquetado
    P_CAP_DEF: 0.004,     // probabilidad de tapa mal roscada
    P_LABEL_DEF: 0.005,   // probabilidad de etiqueta defectuosa
    H: 0.05               // s  paso interno de integración
};

// ---------- Utilidades ----------
function gauss() { // Box-Muller, N(0,1)
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
const r2 = x => Math.round(x * 100) / 100;

function init() {
    return {
        simT: 0, lastWall: Date.now(), startedAt: new Date().toISOString(),
        run: false, sp: P.NOMINAL, v: 0, phase: 0, holding: false,
        Q: P.Q_NOM, qN: 0,
        buffer: P.BUF_MAX, gapLeft: 0,
        caps: P.CAP_MAX,
        pk: [null, null, null, null, null], // 0 entrada,1 llenado,2 tapado,3 etiquetado,4 inspección
        nextId: 1,
        faults: { caps: false, fill: false, bottles: false, jam: false },
        cnt: { total: 0, good: 0, rej: 0, cause: { NIVEL_BAJO: 0, NIVEL_ALTO: 0, TAPA: 0, ETIQUETA: 0 } },
        tm: { planned: 0, up: 0, blocked: 0, starved: 0 },
        blk: { capper: 0, labeler: 0 }, starvedFor: 0,
        lastFill: null, lastFillTime: null,
        events: []
    };
}

let s = context.get('s');
if (!s) { s = init(); context.set('s', s); }

// =====================================================================
// 1) COMANDOS (ya validados por la pestaña de control)
// =====================================================================
if (msg.topic === 'cmd') {
    const c = msg.payload || {};
    let detail = '';
    switch (c.action) {
        case 'start':
            detail = s.run ? 'La línea ya estaba en marcha' : 'Línea arrancando (rampa ' + P.ACC + ' env/min/s)';
            s.run = true; break;
        case 'stop':
            detail = s.run ? 'Línea deteniéndose' : 'La línea ya estaba detenida';
            s.run = false; break;
        case 'setSpeed':
            detail = 'Consigna ' + r2(s.sp) + ' → ' + c.value + ' envases/min';
            s.sp = Number(c.value); break;
        case 'fault':
            s.faults[c.fault] = !!c.active;
            detail = 'Perturbación "' + c.fault + '" ' + (c.active ? 'ACTIVADA' : 'retirada'); break;
        case 'resetCounters':
            s.cnt = init().cnt; s.tm = init().tm; s.lastFill = null; s.lastFillTime = null;
            detail = 'Contadores y tiempos reiniciados'; break;
        default:
            detail = 'Acción desconocida';
    }
    context.set('s', s);
    return [null, { topic: 'cmdResult', payload: {
        cmdId: c.cmdId, action: c.action, value: c.value, source: c.source,
        result: 'accepted', executed: true, detail: detail,
        stateAfter: { run: s.run, speedSetpoint: s.sp, faults: Object.assign({}, s.faults) }
    } }];
}

if (msg.topic !== 'tick') return null;

// =====================================================================
// 2) INTEGRACIÓN EN EL TIEMPO (dt real, sub-pasos de 50 ms)
// =====================================================================
const now = Date.now();
const dt = clamp((now - s.lastWall) / 1000, 0, 2);
s.lastWall = now;
s.events = [];
const n = Math.max(1, Math.ceil(dt / P.H));
const h = dt / n;
for (let i = 0; i < n; i++) step(h);

function newBottle() {
    return { id: s.nextId++, fill: 0, fillDone: false, fillT: 0,
             capOn: false, capT: 0, capped: false, labT: 0, labeled: false,
             defects: [], reject: false, cause: null };
}

function step(h) {
    s.simT += h;
    // --- Perturbación del caudal: proceso de Ornstein-Uhlenbeck (presión del tanque pulmón)
    s.qN += (-s.qN / P.Q_TAU) * h + P.Q_SD * Math.sqrt(2 / P.Q_TAU) * Math.sqrt(h) * gauss();
    s.Q = P.Q_NOM * (s.faults.fill ? P.FILL_FAULT : 1) * (1 + s.qN);

    // --- Alimentación de envases (despaletizador con micro-paradas aleatorias)
    if (s.gapLeft > 0) s.gapLeft -= h;
    else if (Math.random() < P.GAP_PROB * h) s.gapLeft = P.GAP_MIN + Math.random() * (P.GAP_MAX - P.GAP_MIN);
    if (!s.faults.bottles && s.gapLeft <= 0) s.buffer = Math.min(P.BUF_MAX, s.buffer + P.SUPPLY / 60 * h);

    // --- Alimentador de tapas
    if (!s.faults.caps) s.caps = Math.min(P.CAP_MAX, s.caps + P.CAP_FEED / 60 * h);

    const working = s.phase >= P.TRANSFER; // zona de trabajo del ciclo

    // --- Estación 1: LLENADO (válvula temporizada por el ciclo, cierra al llegar al objetivo)
    const b1 = s.pk[1];
    if (b1 && working && !b1.fillDone) {
        b1.fill += s.Q * h / P.VB * 100;   // dL/dt = Q / Vb · 100   [%/s]
        b1.fillT += h;
        if (b1.fill >= P.TARGET) { b1.fill = clamp(P.TARGET + gauss() * P.CLOSE_SD, 0, 100); b1.fillDone = true; }
    }
    // --- Estación 2: TAPADO (consume 1 tapa por envase)
    const b2 = s.pk[2];
    if (b2 && working && !b2.capped) {
        if (!b2.capOn && s.caps >= 1) { s.caps -= 1; b2.capOn = true; }
        if (b2.capOn) {
            b2.capT += h;
            if (b2.capT >= P.T_CAP) { b2.capped = true; if (Math.random() < P.P_CAP_DEF) b2.defects.push('TAPA'); }
        }
    }
    // --- Estación 3: ETIQUETADO
    const b3 = s.pk[3];
    if (b3 && working && !b3.labeled && !s.faults.jam) {
        b3.labT += h;
        if (b3.labT >= P.T_LABEL) { b3.labeled = true; if (Math.random() < P.P_LABEL_DEF) b3.defects.push('ETIQUETA'); }
    }

    // --- Bloqueos de estación
    const capBlocked = !!(b2 && working && !b2.capped && !b2.capOn && s.caps < 1);
    const labBlocked = s.faults.jam;
    s.blk.capper = capBlocked ? s.blk.capper + h : 0;
    s.blk.labeler = labBlocked ? s.blk.labeler + h : 0;

    // --- Dinámica del motor: la velocidad converge a la consigna con aceleración limitada
    const target = (s.run && !s.holding) ? s.sp : 0;
    s.v += clamp(target - s.v, -P.ACC * h, P.ACC * h);
    if (s.v < 1e-6) s.v = 0;

    // --- Avance del ciclo: fase 0→1 a razón de v/60 ciclos por segundo
    if (s.phase < 1) s.phase += s.v / 60 * h;
    if (s.phase >= 1) {
        const canIndex = !(b2 && !b2.capped) && !(b3 && !b3.labeled) && !s.faults.jam;
        if (canIndex && (s.run || s.v > 0)) { indexLine(); s.phase = Math.max(0, s.phase - 1); s.holding = false; }
        else { s.phase = 1; s.holding = s.run && !canIndex; }
    }

    // --- Contabilidad de tiempos (disponibilidad)
    const starved = s.run && s.buffer < 1;
    s.starvedFor = starved ? s.starvedFor + h : 0;
    if (s.run) {
        s.tm.planned += h;
        if (s.holding || capBlocked || labBlocked) s.tm.blocked += h;
        else if (starved) s.tm.starved += h;
        else if (s.v > 0.1) s.tm.up += h;
    }
}

function inspect(b) {
    const dev = b.fill - P.TARGET;
    if (dev < -P.TOL) { b.reject = true; b.cause = 'NIVEL_BAJO'; }
    else if (dev > P.TOL) { b.reject = true; b.cause = 'NIVEL_ALTO'; }
    else if (b.defects.length) { b.reject = true; b.cause = b.defects[0]; }
    s.lastFill = b.fill; s.lastFillTime = b.fillT;
    s.events.push({ type: 'inspect', id: b.id, t: r2(s.simT), fill: r2(b.fill), fillOk: Math.abs(dev) <= P.TOL, reject: b.reject, cause: b.cause });
}

function indexLine() {
    const out = s.pk[4];
    if (out) {
        s.cnt.total++;
        if (out.reject) { s.cnt.rej++; s.cnt.cause[out.cause] = (s.cnt.cause[out.cause] || 0) + 1; } else s.cnt.good++;
        s.events.push({ type: 'exit', id: out.id, t: r2(s.simT), reject: out.reject, cause: out.cause });
    }
    s.pk[4] = s.pk[3]; if (s.pk[4]) inspect(s.pk[4]);
    s.pk[3] = s.pk[2]; s.pk[2] = s.pk[1]; s.pk[1] = s.pk[0];
    if (s.run && s.buffer >= 1) { s.buffer -= 1; s.pk[0] = newBottle(); } else s.pk[0] = null;
}

// =====================================================================
// 3) ESTADOS DE ESTACIÓN Y DE LÍNEA
// =====================================================================
const transferring = s.phase < P.TRANSFER && s.v > 0;
const idle = !s.run && s.v === 0;
function st(b, busyName, done, extraBlocked) {
    if (extraBlocked) return 'BLOQUEADA';
    if (!b) return idle ? 'PARADA' : 'ESPERA';
    if (transferring) return 'TRANSFERENCIA';
    if (!done) return busyName;
    return idle ? 'PARADA' : 'LISTA';
}
const b1 = s.pk[1], b2 = s.pk[2], b3 = s.pk[3], b4 = s.pk[4];
const capWaiting = !!(b2 && !b2.capped && !b2.capOn && s.caps < 1);
const stations = {
    infeed:     { name: 'Alimentación', state: s.buffer < 1 ? (s.run ? 'SIN_ENVASES' : 'VACIA') : (idle ? 'PARADA' : 'OK'), fault: s.faults.bottles ? 'SIN_SUMINISTRO' : (s.gapLeft > 0 ? 'MICROPARADA' : null), buffer: Math.floor(s.buffer) },
    filler:     { name: 'Llenadora', state: st(b1, 'LLENANDO', b1 && b1.fillDone, false), fault: s.faults.fill ? 'BOQUILLA_OBSTRUIDA' : null, flow: r2(s.Q) },
    capper:     { name: 'Tapadora', state: capWaiting ? 'BLOQUEADA' : st(b2, b2 && b2.capOn ? 'TAPANDO' : 'ESPERA_TAPA', b2 && b2.capped, false), fault: s.faults.caps ? 'SIN_TAPAS' : null, caps: Math.floor(s.caps) },
    labeler:    { name: 'Etiquetadora', state: st(b3, 'ETIQUETANDO', b3 && b3.labeled, s.faults.jam), fault: s.faults.jam ? 'ATASCO' : null },
    inspection: { name: 'Inspección', state: b4 ? (b4.reject ? 'RECHAZO' : 'OK') : (idle ? 'PARADA' : 'ESPERA'), fault: null }
};
const anyBlocked = stations.capper.state === 'BLOQUEADA' || stations.labeler.state === 'BLOQUEADA';
let lineState;
if (!s.run) lineState = s.v > 0.05 ? 'DETENIENDO' : 'PARADA';
else if (s.holding || anyBlocked) lineState = 'BLOQUEADA';
else if (s.buffer < 1) lineState = 'SIN_ENVASES';
else if (s.v < s.sp - 0.5) lineState = 'ACELERANDO';
else if (s.v > s.sp + 0.5) lineState = 'DESACELERANDO';
else lineState = 'PRODUCIENDO';

context.set('s', s);
node.status({ fill: lineState === 'PRODUCIENDO' ? 'green' : (lineState === 'PARADA' ? 'grey' : 'yellow'), shape: 'dot',
              text: lineState + ' · ' + r2(s.v) + ' env/min · ' + s.cnt.total + ' env' });

// =====================================================================
// 4) INSTANTÁNEA HACIA LÓGICA DE CONTROL / COMUNICACIONES
// =====================================================================
const pockets = s.pk.map(b => b ? { id: b.id, fill: r2(b.fill), filling: !b.fillDone && b === b1, capped: b.capped, labeled: b.labeled, reject: b.reject, cause: b.cause } : null);
return [{ topic: 'snapshot', payload: {
    simT: r2(s.simT), ts: new Date(now).toISOString(), startedAt: s.startedAt,
    line: { state: lineState, run: s.run, speedSetpoint: s.sp, speed: r2(s.v), phase: Math.round(s.phase * 1000) / 1000, holding: s.holding },
    fill: { level: b1 ? r2(b1.fill) : 0, last: s.lastFill === null ? null : r2(s.lastFill), flow: r2(s.Q), lastTime: s.lastFillTime === null ? null : r2(s.lastFillTime), target: P.TARGET, tol: P.TOL },
    counts: { total: s.cnt.total, good: s.cnt.good, rejected: s.cnt.rej, byCause: Object.assign({}, s.cnt.cause) },
    buffer: Math.floor(s.buffer), caps: Math.floor(s.caps),
    stations: stations,
    blocked: { capper: r2(s.blk.capper), labeler: r2(s.blk.labeler) }, starvedFor: r2(s.starvedFor),
    times: { planned: r2(s.tm.planned), up: r2(s.tm.up), blocked: r2(s.tm.blocked), starved: r2(s.tm.starved) },
    faults: Object.assign({}, s.faults),
    pockets: pockets,
    events: s.events,
    params: P
} }, null];

// =====================================================================
// A07 · CÁLCULO DE KPI
// Entrada: instantánea del modelo (cada 0,5 s)
// Salida: misma instantánea + objeto kpi
// Ventana móvil: diferencia entre contadores acumulados ahora y hace W s.
// =====================================================================
const W = 60;              // s   ventana móvil
const NOMINAL = 24;        // envases/min
const T_IDEAL = 60 / NOMINAL; // s  tiempo de ciclo ideal = 2,5 s
const r1 = x => (x === null || !isFinite(x)) ? null : Math.round(x * 10) / 10;
const r2 = x => (x === null || !isFinite(x)) ? null : Math.round(x * 100) / 100;

const snap = msg.payload;
const t = snap.simT;
let ring = context.get('ring') || [];
let exits = context.get('exits') || [];
let lastTotal = context.get('lastTotal');

// Si se reiniciaron los contadores, se reinician las ventanas
if (lastTotal !== undefined && snap.counts.total < lastTotal) { ring = []; exits = []; }
context.set('lastTotal', snap.counts.total);

ring.push({ t: t, planned: snap.times.planned, up: snap.times.up, total: snap.counts.total, good: snap.counts.good, rej: snap.counts.rejected });
while (ring.length > 2 && t - ring[1].t >= W) ring.shift();
const a = ring[0], b = ring[ring.length - 1];
const span = Math.max(b.t - a.t, 0.001);

for (const e of snap.events) if (e.type === 'exit') exits.push(e.t);
while (exits.length > 11) exits.shift();

// ---- KPI en ventana móvil ----
const dGood = b.good - a.good, dTot = b.total - a.total, dRej = b.rej - a.rej;
const dPlanned = b.planned - a.planned, dUp = b.up - a.up;
const unitsPerMin = dGood / span * 60;                                 // u/min
const rejectPct = dTot > 0 ? dRej / dTot * 100 : 0;                    // %
const availability = dPlanned > 0.5 ? dUp / dPlanned * 100 : null;     // %
const performance = dUp > 0.5 ? Math.min(100, dTot * T_IDEAL / dUp * 100) : null; // %
let cycleTime = null;                                                  // s
if (exits.length >= 2) cycleTime = (exits[exits.length - 1] - exits[0]) / (exits.length - 1);
const quality = dTot > 0 ? (dTot - dRej) / dTot * 100 : null;
const oee = (availability !== null && performance !== null && quality !== null) ? availability * performance * quality / 10000 : null;

// ---- KPI acumulados desde el último reinicio ----
const c = snap.counts, tm = snap.times;
const cum = {
    rejectPct: c.total > 0 ? r2(c.rejected / c.total * 100) : 0,
    availability: tm.planned > 0.5 ? r1(tm.up / tm.planned * 100) : null,
    performance: tm.up > 0.5 ? r1(Math.min(100, c.total * T_IDEAL / tm.up * 100)) : null,
    unitsPerMin: tm.planned > 0.5 ? r1(c.good / tm.planned * 60) : 0
};

snap.kpi = {
    window_s: Math.round(span),
    unitsPerMin: r1(unitsPerMin),
    rejectPct: r2(rejectPct),
    performance: r1(performance),
    cycleTime: r2(cycleTime),
    idealCycleTime: r2(snap.line.speedSetpoint > 0 ? 60 / snap.line.speedSetpoint : null),
    availability: r1(availability),
    quality: r1(quality),
    oee: r1(oee),
    cumulative: cum
};

context.set('ring', ring);
context.set('exits', exits);
node.status({ fill: 'blue', shape: 'dot', text: 'u/min ' + snap.kpi.unitsPerMin + ' · rech ' + snap.kpi.rejectPct + '% · disp ' + snap.kpi.availability + '%' });
return msg;

// =====================================================================
// A07 · MOTOR DE ALARMAS (detección, severidad, reconocimiento)
// Entradas:
//   topic "snapshot" -> instantánea con KPI (evalúa condiciones)
//   topic "ackAlarm" -> comando de reconocimiento validado
// Salidas:
//   1 -> instantánea (+ resumen de alarmas) hacia comunicaciones/telemetría
//   2 -> eventos de alarma (RAISE / ACK / CLEAR) + lista de activas
//   3 -> ACK del comando ackAlarm
// Ciclo de vida (ISA-18.2 simplificado):
//   NORMAL -> ACTIVA_NO_RECONOCIDA -> ACTIVA_RECONOCIDA -> NORMAL
//                                  \-> NORMALIZADA_NO_RECONOCIDA -> NORMAL
// =====================================================================
const DEF = {
    NIVEL_INCORRECTO:   { name: 'Nivel de llenado incorrecto', severity: 'MEDIA', priority: 2,
                          condition: '≥ 2 envases consecutivos fuera de 95 ± 2 %', clearCond: '5 envases consecutivos dentro de tolerancia' },
    ESTACION_BLOQUEADA: { name: 'Estación bloqueada', severity: 'ALTA', priority: 1,
                          condition: 'tapadora o etiquetadora bloqueada ≥ 3 s', clearCond: 'ninguna estación bloqueada' },
    FALTA_ENVASES:      { name: 'Falta de envases', severity: 'MEDIA', priority: 2,
                          condition: 'mesa de alimentación vacía ≥ 4 s con la línea en marcha', clearCond: 'mesa con ≥ 5 envases' }
};
const BAD_N = 2, GOOD_N = 5, BLOCK_S = 3, STARVE_S = 4, STARVE_CLEAR = 5;

let A = context.get('A');
if (!A) {
    A = {};
    for (const k in DEF) A[k] = { code: k, state: 'NORMAL', active: false, acked: true, occurrence: 0, alarmId: null, raisedAt: null, ackAt: null, clearedAt: null, ackBy: null, value: null, message: '' };
    context.set('A', A);
    context.set('streak', { bad: 0, good: 0 });
}
const nowIso = new Date().toISOString();
const events = [];

function publicView(a) {
    const d = DEF[a.code];
    return { alarmId: a.alarmId, code: a.code, name: d.name, severity: d.severity, priority: d.priority,
             state: a.state, active: a.active, acked: a.acked, condition: d.condition, value: a.value, message: a.message,
             raisedAt: a.raisedAt, ackAt: a.ackAt, ackBy: a.ackBy, clearedAt: a.clearedAt };
}
function emit(a, ev) { events.push(Object.assign({ event: ev, eventTs: nowIso }, publicView(a))); }
function setState(a) {
    a.state = a.active ? (a.acked ? 'ACTIVA_RECONOCIDA' : 'ACTIVA_NO_RECONOCIDA') : (a.acked ? 'NORMAL' : 'NORMALIZADA_NO_RECONOCIDA');
}
function evaluate(code, condTrue, condClear, value, message) {
    const a = A[code];
    if (!a.active && condTrue) {
        a.active = true; a.acked = false; a.occurrence++;
        a.alarmId = 'A07-' + code + '-' + a.occurrence;
        a.raisedAt = nowIso; a.ackAt = null; a.ackBy = null; a.clearedAt = null;
        a.value = value; a.message = message; setState(a); emit(a, 'RAISE');
    } else if (a.active && condClear) {
        a.active = false; a.clearedAt = nowIso; a.value = value; setState(a); emit(a, 'CLEAR');
    } else if (a.active) { a.value = value; }
}
function activeList() {
    return Object.values(A).filter(a => a.state !== 'NORMAL').map(publicView).sort((x, y) => DEF[x.code].priority - DEF[y.code].priority);
}

// ---------------- Reconocimiento ----------------
if (msg.topic === 'ackAlarm') {
    const cmd = msg.payload;
    const a = Object.values(A).find(x => x.alarmId === cmd.alarmId || x.code === cmd.alarmId);
    let result = 'accepted', detail;
    if (!a || a.alarmId === null) { result = 'rejected'; detail = 'Alarma no encontrada: ' + cmd.alarmId; }
    else if (a.acked) { detail = 'La alarma ' + a.alarmId + ' ya estaba reconocida'; }
    else {
        a.acked = true; a.ackAt = nowIso; a.ackBy = cmd.source || cmd.user || 'operador'; setState(a); emit(a, 'ACK');
        detail = 'Alarma ' + a.alarmId + ' reconocida → ' + a.state;
    }
    context.set('A', A);
    return [null,
            events.length ? { topic: 'alarms', payload: { events: events, active: activeList() } } : null,
            { topic: 'cmdResult', payload: { cmdId: cmd.cmdId, action: 'ackAlarm', alarmId: cmd.alarmId, source: cmd.source, result: result, executed: result === 'accepted', detail: detail } }];
}

// ---------------- Evaluación de condiciones ----------------
const snap = msg.payload;
const streak = context.get('streak');
for (const e of snap.events) {
    if (e.type !== 'inspect') continue;
    if (e.fillOk) { streak.good++; streak.bad = 0; } else { streak.bad++; streak.good = 0; }
    streak.lastFill = e.fill;
}
context.set('streak', streak);

evaluate('NIVEL_INCORRECTO', streak.bad >= BAD_N, streak.good >= GOOD_N, streak.lastFill === undefined ? null : streak.lastFill,
         'Último llenado ' + streak.lastFill + ' % (objetivo 95 ± 2 %)');

const bCap = snap.blocked.capper, bLab = snap.blocked.labeler;
const who = bLab >= BLOCK_S ? 'Etiquetadora (atasco)' : 'Tapadora (tolva sin tapas)';
evaluate('ESTACION_BLOQUEADA', Math.max(bCap, bLab) >= BLOCK_S, bCap === 0 && bLab === 0, Math.max(bCap, bLab),
         who + ' bloqueada ' + Math.round(Math.max(bCap, bLab)) + ' s');

evaluate('FALTA_ENVASES', snap.line.run && snap.starvedFor >= STARVE_S, snap.buffer >= STARVE_CLEAR, snap.buffer,
         'Mesa de alimentación con ' + snap.buffer + ' envases');

// ---------------- Salidas ----------------
const act = activeList();
snap.alarms = { active: act.length, unacked: act.filter(a => !a.acked).length, highest: act.length ? act[0].severity : null };
context.set('A', A);
node.status({ fill: act.length ? 'red' : 'green', shape: act.length ? 'ring' : 'dot', text: act.length ? act.length + ' alarma(s): ' + act.map(a => a.code).join(', ') : 'sin alarmas' });
return [msg, events.length ? { topic: 'alarms', payload: { events: events, active: act } } : null, null];

// =====================================================================
// A07 · VALIDADOR DE COMANDOS Y ENCLAVAMIENTOS (lógica de control)
// Entradas:
//   msg.topic = "state"   -> última instantánea del modelo (para enclavamientos)
//   msg.topic = "command" -> payload crudo recibido por MQTT (string)
// Salidas:
//   1 -> comando aceptado hacia el MODELO (topic "cmd")
//   2 -> reconocimiento de alarma hacia el MOTOR DE ALARMAS (topic "ackAlarm")
//   3 -> ACK de rechazo / duplicado directo a comunicaciones
// =====================================================================
const SP_MIN = 6, SP_MAX = 30;
const DEDUP_WINDOW_MS = 10 * 60 * 1000;   // ventana de memoria de cmdId
const DEBOUNCE_MS = 1500;                 // anti doble-pulsación para comandos de texto
const MAX_AGE_MS = 60 * 1000;             // comandos más antiguos se consideran expirados
const FAULTS = ['caps', 'fill', 'bottles', 'jam'];

if (msg.topic === 'state') { context.set('last', msg.payload); return null; }

const nowMs = Date.now();
const seen = context.get('seen') || {};        // cmdId -> instante de recepción
const recent = context.get('recent') || {};    // firma de comando de texto -> instante
for (const k in seen) if (nowMs - seen[k] > DEDUP_WINDOW_MS) delete seen[k];
for (const k in recent) if (nowMs - recent[k] > DEBOUNCE_MS) delete recent[k];

function reject(cmd, reason, result) {
    node.status({ fill: 'red', shape: 'ring', text: (result || 'rejected') + ': ' + reason });
    return [null, null, { topic: 'cmdResult', payload: {
        cmdId: cmd.cmdId || null, action: cmd.action || null, value: cmd.value, source: cmd.source || null,
        result: result || 'rejected', executed: false, detail: reason } }];
}

// ---------- 1) Decodificación: JSON o texto simple (IoT MQTT Panel) ----------
let raw = msg.payload;
if (Buffer.isBuffer(raw)) raw = raw.toString('utf8');
let cmd = null;
if (typeof raw === 'object' && raw !== null) cmd = raw;
else {
    const txt = String(raw).trim();
    if (txt.startsWith('{')) {
        try { cmd = JSON.parse(txt); } catch (e) { return reject({}, 'JSON inválido: ' + e.message); }
    } else {
        // Formatos de texto aceptados: START | STOP | SPEED:18 | ACK:<alarmId>
        const m = txt.toUpperCase().match(/^(START|STOP|SPEED|ACK)(?::\s*(.+))?$/);
        if (!m) return reject({}, 'Formato no reconocido: "' + txt.slice(0, 40) + '"');
        const map = { START: 'start', STOP: 'stop', SPEED: 'setSpeed', ACK: 'ackAlarm' };
        cmd = { action: map[m[1]], source: 'texto' };
        if (m[1] === 'SPEED') cmd.value = Number(m[2]);
        if (m[1] === 'ACK') cmd.alarmId = txt.split(':').slice(1).join(':').trim();
        const sig = cmd.action + '|' + (cmd.value || cmd.alarmId || '');
        if (recent[sig]) { context.set('recent', recent); return reject(cmd, 'Repetición en menos de ' + DEBOUNCE_MS + ' ms (anti-rebote)', 'duplicate'); }
        recent[sig] = nowMs;
        cmd.cmdId = 'txt-' + nowMs.toString(36) + '-' + Math.floor(Math.random() * 1e4);
    }
}
context.set('recent', recent);

// ---------- 2) Identificación y prevención de duplicados ----------
if (!cmd.cmdId || typeof cmd.cmdId !== 'string') return reject(cmd, 'Falta cmdId (identificador único del comando)');
if (seen[cmd.cmdId]) return reject(cmd, 'cmdId ya procesado: no se ejecuta dos veces', 'duplicate');
seen[cmd.cmdId] = nowMs;
context.set('seen', seen);

if (cmd.ts) {
    const age = nowMs - Date.parse(cmd.ts);
    if (!isNaN(age) && age > MAX_AGE_MS) return reject(cmd, 'Comando expirado (' + Math.round(age / 1000) + ' s de antigüedad)', 'expired');
}

// ---------- 3) Validación de acción y rango ----------
const last = context.get('last');
switch (cmd.action) {
    case 'start':
        if (last && last.faults && last.faults.jam)
            return reject(cmd, 'Enclavamiento: etiquetadora atascada. Retire el atasco antes de arrancar');
        break;
    case 'stop':
        break; // la parada siempre se acepta (seguridad)
    case 'setSpeed': {
        const v = Number(cmd.value);
        if (!isFinite(v)) return reject(cmd, 'value debe ser numérico (envases/min)');
        if (v < SP_MIN || v > SP_MAX) return reject(cmd, 'Consigna fuera de rango [' + SP_MIN + ', ' + SP_MAX + '] envases/min');
        cmd.value = Math.round(v * 10) / 10;
        break;
    }
    case 'fault':
        if (FAULTS.indexOf(cmd.fault) < 0) return reject(cmd, 'fault debe ser uno de: ' + FAULTS.join(', '));
        cmd.active = !!cmd.active;
        break;
    case 'resetCounters':
        if (last && last.line && last.line.run) return reject(cmd, 'Enclavamiento: detenga la línea antes de reiniciar contadores');
        break;
    case 'ackAlarm':
        if (!cmd.alarmId) return reject(cmd, 'Falta alarmId');
        node.status({ fill: 'blue', shape: 'dot', text: 'ackAlarm ' + cmd.alarmId });
        return [null, { topic: 'ackAlarm', payload: cmd }, null];
    default:
        return reject(cmd, 'Acción no soportada: ' + cmd.action);
}

node.status({ fill: 'green', shape: 'dot', text: cmd.action + (cmd.value !== undefined ? ' ' + cmd.value : '') + ' (' + cmd.cmdId + ')' });
return [{ topic: 'cmd', payload: cmd }, null, null];

// =====================================================================
// A07 · EMPAQUETADO MQTT DE TELEMETRÍA Y ESTADO (lado simulador)
// Salida 1 -> utm/iot/A07/telemetry  (QoS 0, sin retain, 2 Hz)
// Salida 2 -> utm/iot/A07/status     (QoS 1, RETAIN, al cambiar o cada 5 s)
// Cada mensaje lleva deviceId, ts ISO 8601, seq y unidades.
// =====================================================================
const DEVICE = 'A07-SIM-01';
const STATUS_EVERY_MS = 5000;
const snap = msg.payload;
const seq = (context.get('seq') || 0) + 1; context.set('seq', seq);

const telemetry = {
    deviceId: DEVICE, project: 'A07', type: 'telemetry', ts: snap.ts, seq: seq,
    units: { lineSpeed: 'envases/min', speedSetpoint: 'envases/min', fillLevel: '%', lastFillLevel: '%', fillFlow: 'mL/s',
             fillTime: 's', bottlesCounted: 'n', infeedBuffer: 'envases', capHopper: 'tapas', cycleTime: 's', unitsPerMin: 'u/min' },
    data: {
        lineState: snap.line.state, run: snap.line.run,
        lineSpeed: snap.line.speed, speedSetpoint: snap.line.speedSetpoint, cyclePhase: snap.line.phase,
        fillLevel: snap.fill.level, lastFillLevel: snap.fill.last, fillFlow: snap.fill.flow, fillTime: snap.fill.lastTime,
        bottlesCounted: snap.counts.total, bottlesGood: snap.counts.good, bottlesRejected: snap.counts.rejected, rejectsByCause: snap.counts.byCause,
        infeedBuffer: snap.buffer, capHopper: snap.caps,
        stations: {
            infeed: snap.stations.infeed.state, filler: snap.stations.filler.state, capper: snap.stations.capper.state,
            labeler: snap.stations.labeler.state, inspection: snap.stations.inspection.state
        },
        pockets: snap.pockets,
        times: snap.times
    },
    kpi: snap.kpi,
    alarms: snap.alarms
};

// ---- Estado: se publica si cambia algo relevante o como latido cada 5 s ----
const sig = JSON.stringify([snap.line.state, snap.line.run, snap.line.speedSetpoint, snap.faults,
    Object.values(snap.stations).map(x => x.state + '/' + x.fault), snap.alarms.active, snap.alarms.unacked]);
const lastSig = context.get('lastSig'), lastAt = context.get('lastAt') || 0;
let status = null;
if (sig !== lastSig || Date.now() - lastAt >= STATUS_EVERY_MS) {
    const sseq = (context.get('sseq') || 0) + 1; context.set('sseq', sseq);
    status = { topic: 'status', payload: {
        deviceId: DEVICE, project: 'A07', type: 'status', ts: snap.ts, seq: sseq, online: true,
        startedAt: snap.startedAt, uptime_s: Math.round(snap.simT),
        lineState: snap.line.state, run: snap.line.run, speedSetpoint: snap.line.speedSetpoint,
        stations: snap.stations, faults: snap.faults, alarms: snap.alarms,
        params: snap.params
    } };
    context.set('lastSig', sig); context.set('lastAt', Date.now());
}
return [{ topic: 'telemetry', payload: telemetry }, status];

// =====================================================================
// A07 · EMPAQUETADO MQTT DE ALARMAS
// Salida 1 -> utm/iot/A07/alarms         (QoS 1, sin retain: cada evento una vez)
// Salida 2 -> utm/iot/A07/alarms/active  (QoS 1, RETAIN: lista vigente para
//             clientes que se conectan o reconectan tarde)
// =====================================================================
const DEVICE = 'A07-SIM-01';
const out1 = msg.payload.events.map(e => {
    const seq = (context.get('seq') || 0) + 1; context.set('seq', seq);
    return { topic: 'alarm', payload: Object.assign({ deviceId: DEVICE, project: 'A07', type: 'alarm', ts: e.eventTs, seq: seq }, e) };
});
const active = { topic: 'active', payload: { deviceId: DEVICE, project: 'A07', type: 'alarms_active', ts: new Date().toISOString(), count: msg.payload.active.length, alarms: msg.payload.active } };
return [out1, active];

// =====================================================================
// A07 · EMPAQUETADO MQTT DE RECONOCIMIENTOS DE COMANDO
// Salida -> utm/iot/A07/ack (QoS 1, sin retain)
// result: accepted | rejected | duplicate | expired
// =====================================================================
const seq = (context.get('seq') || 0) + 1; context.set('seq', seq);
const r = msg.payload;
msg.payload = Object.assign({ deviceId: 'A07-SIM-01', project: 'A07', type: 'ack', ts: new Date().toISOString(), seq: seq }, r);
node.status({ fill: r.result === 'accepted' ? 'green' : 'red', shape: 'dot', text: r.result + ' · ' + (r.action || '?') + ' · ' + (r.cmdId || '') });
return msg;

template:
/* =====================================================================
   A07 · Dashboard HMI — estilo ISA-101 (alto desempeño):
   fondo gris neutro, el color se reserva para estados anormales.
   ===================================================================== */
:root {
  --bg: #d9dde1;
  --panel: #eceef0;
  --panel-2: #e2e5e8;
  --line: #b4bcc4;
  --ink: #1b2229;
  --ink-2: #4a5560;
  --muted: #6d7883;
  --steel: #8b96a1;
  --steel-d: #5f6b77;
  --work: #2f6fb3;      /* actividad normal (azul discreto) */
  --ok: #2e7d4f;
  --med: #d9930d;       /* severidad MEDIA */
  --high: #c62f2a;      /* severidad ALTA */
  --liquid: #c9772b;    /* producto (bebida ámbar) */
  --glass: #f6f8f9;
  --radius: 6px;
  --mono: ui-monospace, "SF Mono", Consolas, "Roboto Mono", monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}
* { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); color: var(--ink); font: 14px/1.4 var(--sans); }
body { min-height: 100vh; }
button { font: inherit; }
code { font-family: var(--mono); font-size: 12px; background: var(--panel-2); padding: 1px 4px; border-radius: 3px; }
.muted { color: var(--muted); }
.small { font-size: 12px; }

/* ---------- Barra superior ---------- */
.topbar {
  position: sticky; top: 0; z-index: 10;
  display: flex; align-items: center; gap: 16px; flex-wrap: wrap;
  padding: 10px 16px; background: #2b333b; color: #e8ecef;
}
.brand { display: flex; align-items: center; gap: 12px; flex: 1 1 280px; }
.tag { font: 700 18px var(--mono); background: #e8ecef; color: #2b333b; padding: 4px 8px; border-radius: 4px; }
.title { font-weight: 600; font-size: 16px; }
.subtitle { font-size: 12px; color: #aab4be; }
.views { display: flex; gap: 4px; background: #1f262c; padding: 3px; border-radius: 6px; }
.view-btn { border: 0; background: transparent; color: #c4ccd3; padding: 6px 16px; border-radius: 4px; cursor: pointer; }
.view-btn.active { background: #e8ecef; color: #1b2229; font-weight: 600; }
.conn { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.pill { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; padding: 3px 8px; border: 1px solid #4a555f; border-radius: 99px; color: #c4ccd3; }
.pill i { width: 8px; height: 8px; border-radius: 50%; background: #6d7883; }
.pill.ok i { background: #5cc286; }
.pill.warn i { background: var(--med); }
.pill.bad i { background: #ff5b55; }
.pill.bad { border-color: #ff5b55; color: #ffd0ce; }
.clock { font: 13px var(--mono); color: #c4ccd3; min-width: 64px; text-align: right; }

main { padding: 16px; max-width: 1500px; margin: 0 auto; }
.view { display: none; }
.view.active { display: block; }

/* ---------- Paneles ---------- */
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 12px 14px; margin-bottom: 14px; }
.panel-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; margin-bottom: 8px; }
.panel-head h2 { font-size: 13px; text-transform: uppercase; letter-spacing: .06em; margin: 0; color: var(--ink-2); }
.lbl { font-size: 11px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }

/* ---------- Cabecera de operación ---------- */
.op-head { display: grid; grid-template-columns: minmax(220px, 1fr) 2fr; gap: 14px; margin-bottom: 14px; }
.state-box { background: var(--panel); border: 1px solid var(--line); border-left: 8px solid var(--steel); border-radius: var(--radius); padding: 12px 16px; }
.state { font: 700 28px var(--sans); letter-spacing: .02em; margin: 2px 0; }
.state-sub { color: var(--ink-2); font-size: 13px; }
.state-box.s-run { border-left-color: var(--ok); }
.state-box.s-trans { border-left-color: var(--work); }
.state-box.s-med { border-left-color: var(--med); background: #f3ead6; }
.state-box.s-high { border-left-color: var(--high); background: #f5dcda; }
.state-box.s-high .state { color: var(--high); }
.controls { margin-bottom: 0; }
.ctl-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 8px; }
.ctl-row.speed label { font-size: 13px; color: var(--ink-2); }
.ctl-row input[type=range] { flex: 1 1 160px; accent-color: var(--steel-d); }
.ctl-row input[type=number] { width: 64px; padding: 6px; border: 1px solid var(--line); border-radius: 4px; font: 14px var(--mono); }
.unit { color: var(--muted); font-size: 12px; }
.btn { border: 1px solid #8f99a3; background: linear-gradient(#f7f8f9, #dde1e5); color: var(--ink); padding: 7px 14px; border-radius: 4px; cursor: pointer; font-weight: 600; }
.btn:hover { background: linear-gradient(#ffffff, #e5e8eb); }
.btn:active { background: #cfd4d9; }
.btn:disabled { opacity: .5; cursor: not-allowed; }
.btn.small { padding: 4px 10px; font-size: 12px; }
.btn-start { border-color: #4a7d5d; }
.btn-stop { border-color: #9b4a47; }
.btn.on { background: var(--med); border-color: #a06d07; color: #1b2229; }
.ack-line { margin-top: 10px; font: 12px var(--mono); color: var(--ink-2); min-height: 18px; padding: 6px 8px; background: var(--panel-2); border-radius: 4px; }
.ack-line.ok { color: var(--ok); }
.ack-line.bad { color: var(--high); background: #f5dcda; }
.ack-line.wait { color: var(--work); }

/* ---------- Mímico SVG ---------- */
.mimic-wrap { padding: 6px; }
#mimic { width: 100%; height: auto; display: block; }
#mimic text { font-family: var(--sans); }
#mimic .st-name { font-size: 13px; font-weight: 600; fill: var(--ink-2); text-anchor: middle; }
#mimic .st-state { font: 600 11px var(--mono); text-anchor: middle; }
#mimic .val { font: 12px var(--mono); fill: var(--ink-2); }

/* ---------- Variables principales ---------- */
.vars { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-bottom: 14px; }
.var { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 14px; }
.var .val { font: 600 30px var(--mono); font-variant-numeric: tabular-nums; }
.var .val small { font: 12px var(--sans); color: var(--muted); margin-left: 6px; }
.var .val.small { font-size: 20px; }
.var .hint { font-size: 12px; color: var(--muted); }
.bar { position: relative; height: 8px; background: var(--panel-2); border: 1px solid var(--line); border-radius: 4px; margin: 6px 0 4px; overflow: hidden; }
.bar b { position: absolute; left: 0; top: 0; bottom: 0; background: var(--steel-d); width: 0; transition: width .4s; }
.bar em { position: absolute; top: -2px; bottom: -2px; width: 2px; background: var(--ink); left: 0; }
.fillbar .tol { position: absolute; left: 93%; width: 4%; top: 0; bottom: 0; background: rgba(46,125,79,.25); }
.fillbar b { background: var(--liquid); }

/* ---------- KPI ---------- */
.kpis { display: grid; grid-template-columns: repeat(6, 1fr); gap: 14px; margin-bottom: 14px; }
.kpi { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 12px; border-top: 4px solid var(--steel); }
.kpi .v { font: 600 24px var(--mono); font-variant-numeric: tabular-nums; }
.kpi .v small { font: 12px var(--sans); color: var(--muted); margin-left: 4px; }
.kpi .f { font-size: 11px; color: var(--muted); margin-top: 2px; }
.kpi.warn { border-top-color: var(--med); }
.kpi.bad { border-top-color: var(--high); }

/* ---------- Tablas ---------- */
.tbl { width: 100%; border-collapse: collapse; font-size: 13px; }
.tbl th { text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); border-bottom: 1px solid var(--line); padding: 6px 8px; position: sticky; top: 0; background: var(--panel); }
.tbl td { border-bottom: 1px solid var(--panel-2); padding: 6px 8px; vertical-align: middle; }
.tbl td.mono { font-family: var(--mono); font-size: 12px; }
.tbl tr.empty td { color: var(--muted); font-style: italic; }
.scroll { max-height: 320px; overflow: auto; }
.scroll.short { max-height: 240px; }
.sev { display: inline-block; font: 700 11px var(--mono); padding: 2px 7px; border-radius: 3px; color: #fff; }
.sev.ALTA { background: var(--high); }
.sev.MEDIA { background: var(--med); color: #1b2229; }
.chip { display: inline-block; font: 600 11px var(--mono); padding: 2px 6px; border-radius: 3px; background: var(--panel-2); color: var(--ink-2); border: 1px solid var(--line); }
.chip.work { color: var(--work); border-color: #9db8d6; }
.chip.bad { background: var(--high); color: #fff; border-color: var(--high); }
.chip.warn { background: var(--med); color: #1b2229; border-color: var(--med); }
.chip.ok { color: var(--ok); }
tr.unack td:first-child { box-shadow: inset 4px 0 0 var(--high); }
tr.blink td { animation: blink 1s steps(2) infinite; }
@keyframes blink { 50% { background: #f5dcda; } }

/* ---------- Ingeniería ---------- */
.seg { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; }
.seg button { border: 1px solid var(--line); background: var(--panel-2); padding: 4px 10px; border-radius: 4px; cursor: pointer; font-size: 12px; }
.seg button.active { background: #2b333b; color: #fff; border-color: #2b333b; }
.charts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.chart { background: #f5f6f7; border: 1px solid var(--line); border-radius: 4px; padding: 8px; }
.chart-title { font-size: 12px; font-weight: 600; color: var(--ink-2); margin-bottom: 4px; }
.chart canvas { width: 100%; height: 200px; display: block; }
.eng-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; }
.eng-grid > .panel { margin-bottom: 0; }
.eng-grid { margin-bottom: 14px; }
.faults { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin: 8px 0; }
.faults .btn { text-align: left; font-weight: 500; }
.kv { display: grid; grid-template-columns: max-content 1fr; gap: 4px 14px; margin: 0; font-size: 13px; }
.kv.cols { grid-template-columns: repeat(4, max-content 1fr); }
.kv dt { color: var(--muted); }
.kv dd { margin: 0; font-family: var(--mono); font-size: 12px; }

.toast { position: fixed; right: 16px; bottom: 16px; max-width: 420px; background: #2b333b; color: #fff; padding: 10px 14px; border-radius: 6px; font-size: 13px; opacity: 0; transform: translateY(10px); transition: all .25s; pointer-events: none; }
.toast.show { opacity: 1; transform: none; }
.toast.bad { background: var(--high); }

/* ---------- Responsivo ---------- */
@media (max-width: 1100px) {
  .kpis { grid-template-columns: repeat(3, 1fr); }
  .charts { grid-template-columns: 1fr; }
  .kv.cols { grid-template-columns: repeat(2, max-content 1fr); }
}
@media (max-width: 760px) {
  main { padding: 10px; }
  .op-head, .eng-grid { grid-template-columns: 1fr; }
  .vars { grid-template-columns: repeat(2, 1fr); }
  .kpis { grid-template-columns: repeat(2, 1fr); }
  .faults { grid-template-columns: 1fr; }
  .kv.cols { grid-template-columns: max-content 1fr; }
  .state { font-size: 22px; }
  .tbl { font-size: 12px; }
}

/* =====================================================================
   A07 · Dashboard propio (HTML/CSS/JS sin librerías externas)
   El navegador NO accede al simulador: recibe por WebSocket lo que la
   pestaña "Presentación" de Node-RED obtiene del broker MQTT, y envía
   comandos que esa pestaña publica en utm/iot/A07/commands.
   ===================================================================== */
(function () {
  'use strict';

  // ------------------------------------------------------------------
  // Estado del cliente
  // ------------------------------------------------------------------
  const S = {
