    tel: null, telAt: 0, status: null, active: null,
    history: [], lastHistSec: 0,
    alarmLog: [], ackLog: [], comms: null,
    pending: {},            // cmdId -> {action, sentAt, timer}
    view: 'op', winS: 300,
    anim: { idx: 0, lastPhase: 0, belt: 0, lastFrame: performance.now(), prevPockets: [], exiting: [] }
  };
  const TRANSFER = 0.25;
  const $ = id => document.getElementById(id);
  const fmt = (v, d = 1) => (v === null || v === undefined || !isFinite(v)) ? '–' : Number(v).toFixed(d);
  const hhmmss = iso => { if (!iso) return '–'; const d = new Date(iso); return d.toLocaleTimeString('es-EC', { hour12: false }); };
  const esc = s => String(s === null || s === undefined ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

  // ------------------------------------------------------------------
  // WebSocket con reconexión automática
  // ------------------------------------------------------------------
  function wsUrl() {
    const base = location.pathname.replace(/a07\/?$/, '');
