  }
  function connect() {
    let ws;
    try { ws = new WebSocket(wsUrl()); } catch (e) { scheduleReconnect(); return; }
    S.ws = ws;
    ws.onopen = () => { S.wsOk = true; S.retry = 0; ws.send(JSON.stringify({ type: 'hello' })); updatePills(); };
    ws.onclose = () => { S.wsOk = false; updatePills(); scheduleReconnect(); };
    ws.onerror = () => { try { ws.close(); } catch (e) { } };
    ws.onmessage = ev => { let m; try { m = JSON.parse(ev.data); } catch (e) { return; } handle(m); };
  }
  function scheduleReconnect() {
    S.retry = Math.min(S.retry + 1, 6);
    setTimeout(connect, Math.min(1000 * Math.pow(1.6, S.retry), 10000));
  }

  function handle(m) {
    switch (m.type) {
      case 'snapshot':
        S.tel = m.telemetry; S.telAt = m.telemetry ? Date.now() : 0;
        S.status = m.status; S.active = m.active; S.comms = m.comms;
        S.history = (m.history || []).slice();
        S.alarmLog = m.alarmLog || []; S.ackLog = m.ackLog || [];
        renderAll(); break;
      case 'telemetry':
        onTelemetry(m.data); S.comms = m.comms; break;
      case 'status':
        S.status = m.data; renderStatus(); updatePills(); break;
      case 'alarm':
        S.alarmLog.push(m.data); if (S.alarmLog.length > 300) S.alarmLog.shift();
        renderAlarmLog();
        if (m.data.event === 'RAISE') toast('ALARMA ' + m.data.severity + ': ' + m.data.name + ' — ' + m.data.message, true);
        break;
      case 'alarms_active':
        S.active = m.data; renderActive(); break;
      case 'ack':
        onAck(m.data); break;
      case 'resync':
        if (S.ws && S.wsOk) S.ws.send(JSON.stringify({ type: 'hello' }));
        break;
      case 'cmd_sent':
        break;
    }
  }

  // ------------------------------------------------------------------
  // Comandos (salen por WebSocket → Node-RED → MQTT /commands)
  // ------------------------------------------------------------------
  function uuid() {
    if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
    return 'web-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
  }
  function sendCmd(action, extra) {
    if (!S.wsOk) { toast('Sin conexión con Node-RED: comando no enviado', true); return; }
    const cmd = Object.assign({ cmdId: uuid(), ts: new Date().toISOString(), source: 'dashboard-web', action: action }, extra || {});
    S.ws.send(JSON.stringify({ type: 'cmd', cmd: cmd }));
    const p = { action: action, sentAt: Date.now() };
    p.timer = setTimeout(() => {
      if (S.pending[cmd.cmdId]) { delete S.pending[cmd.cmdId]; setAckLine('Sin ACK en 5 s para "' + action + '" (¿simulador desconectado?)', 'bad'); }
    }, 5000);
    S.pending[cmd.cmdId] = p;
    setAckLine('→ ' + action + (extra && extra.value !== undefined ? ' ' + extra.value : '') + ' enviado · cmdId ' + cmd.cmdId.slice(0, 8) + '… esperando ACK', 'wait');
  }
  function onAck(a) {
    S.ackLog.push(a); if (S.ackLog.length > 50) S.ackLog.shift();
    const p = S.pending[a.cmdId];
    if (p) {
      clearTimeout(p.timer); delete S.pending[a.cmdId];
      const rtt = Date.now() - p.sentAt;
      const ok = a.result === 'accepted';
      setAckLine((ok ? '✔ ACK ' : '✖ ') + a.result + ' · ' + a.action + ' · ' + (a.detail || '') + ' · ' + rtt + ' ms', ok ? 'ok' : 'bad');
      if (!ok) toast('Comando ' + a.result + ': ' + a.detail, true);
    }
    renderAckLog();
  }
  function setAckLine(t, cls) { const el = $('ack-line'); el.textContent = t; el.className = 'ack-line ' + (cls || ''); }
  let toastTimer;
  function toast(t, bad) {
    const el = $('toast'); el.textContent = t; el.className = 'toast show' + (bad ? ' bad' : '');
    clearTimeout(toastTimer); toastTimer = setTimeout(() => { el.className = 'toast'; }, 4500);
  }

  // ------------------------------------------------------------------
  // Telemetría
  // ------------------------------------------------------------------
  function onTelemetry(t) {
    const prev = S.tel;
    S.tel = t; S.telAt = Date.now();
    // índice de ciclo para animar la banda
    if (prev && t.data.cyclePhase < prev.data.cyclePhase - 0.3) S.anim.idx++;
    detectExits(prev, t);
    // histórico a 1 muestra/s
    const ms = Date.parse(t.ts), sec = Math.floor(ms / 1000);
    if (sec !== S.lastHistSec) {
      S.lastHistSec = sec;
      const d = t.data, k = t.kpi || {};
      S.history.push([ms, d.lineSpeed, d.speedSetpoint, d.lastFillLevel, k.unitsPerMin, k.rejectPct, k.availability]);
      if (S.history.length > 3600) S.history.shift();
    }
    renderOp();
  }
  function detectExits(prev, t) {
    if (!prev) return;
    const was = prev.data.pockets[4];
    const ids = t.data.pockets.filter(Boolean).map(b => b.id);
    if (was && ids.indexOf(was.id) < 0) S.anim.exiting.push({ b: was, start: performance.now() });
  }

  // ------------------------------------------------------------------
  // Render: operación
  // ------------------------------------------------------------------
  const STATE_TXT = {
