    el('circle', { r: 32, fill: '#f6f8f9', stroke: '#5f6b77', 'stroke-width': 1.5 }, E.roll);
    el('circle', { r: 10, fill: '#5f6b77' }, E.roll);
    for (let i = 0; i < 4; i++) el('line', { x1: 0, y1: 0, x2: 30 * Math.cos(i * Math.PI / 2), y2: 30 * Math.sin(i * Math.PI / 2), stroke: '#8b96a1', 'stroke-width': 2 }, E.roll);
    E.web = el('path', { d: `M${L + 70} 202 L${L + 30} 266 L${L + 17} 266`, fill: 'none', stroke: '#e9d27a', 'stroke-width': 4 });
