  }

  function frame(now) {
    const A = S.anim;
    const dtf = Math.min(0.1, (now - A.lastFrame) / 1000); A.lastFrame = now;
    const t = S.tel;
    if (t) {
      const d = t.data;
      const age = Math.min(1, (Date.now() - S.telAt) / 1000);
      const stale = Date.now() - S.telAt > 3000;
      const v = stale ? 0 : d.lineSpeed;
      let ph = d.cyclePhase;
      if (!stale && ph < 1) ph = Math.min(1, ph + v / 60 * age);
      const moveFrac = ph < TRANSFER && v > 0 ? ph / TRANSFER : 1;
      // banda: avanza un paso por ciclo durante la transferencia
      const beltX = ((A.idx + (ph < TRANSFER ? ph / TRANSFER : 1)) * PITCH) % 30;
      E.beltPat.setAttribute('patternTransform', 'translate(' + beltX.toFixed(1) + ',0)');
