    for (let i = 0; i <= 4; i++) { const t = o.tMin + (o.tMax - o.tMin) * i / 4; const x = X(t); g.fillText(new Date(t).toLocaleTimeString('es-EC', { hour12: false, hour: '2-digit', minute: '2-digit', second: S.winS <= 300 ? '2-digit' : undefined }), Math.min(x - 18, w - 46), h - 5); }
    if (o.band) { g.fillStyle = 'rgba(46,125,79,.14)'; g.fillRect(L, Y(o.band[1]), pw, Y(o.band[0]) - Y(o.band[1])); }
