// =====================================================================
// A07 · PASARELA DEL DASHBOARD (capa de presentación)
// Esta pestaña es un CLIENTE MQTT independiente del simulador: solo conoce
// lo que llega por el broker. Reenvía los datos al navegador por WebSocket
// y publica en /commands lo que el operador ordena desde la interfaz.
// Entradas: mqtt in (telemetry, status, alarms, alarms/active, ack),
//           websocket in (navegador), restore/* (archivos al arrancar)
// Salidas: 1 WebSocket → navegador | 2 MQTT → utm/iot/A07/commands
//          3 archivo alarmas.jsonl | 4 archivo historico-AAAA-MM-DD.csv
//          5 archivo eventos.jsonl (comandos y ACK)
// =====================================================================
const HIST_MAX_S = 3600;  // se conservan 60 min de histórico (1 muestra/s)
const LOG_MAX = 300;
const BASE = 'utm/iot/A07/';

function dataDir() {
    const d = env.get('A07_DATA_DIR');
    if (d) return d;
    return (env.get('HOME') || env.get('USERPROFILE') || '.') + '/.node-red/a07-data';
}
function today() { const d = new Date(); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }

let G = context.get('G');
let fresh = false;
if (!G) {
    fresh = true;
    G = { telemetry: null, status: null, active: null, history: [], alarmLog: [], ackLog: [], lastSampleSec: 0,
          comms: { rx: {}, lastRxAt: null, lastSeq: null, seqGaps: 0, parseErrors: 0, cmdsSent: 0, latencyMs: null, since: new Date().toISOString() } };
}
const out = [null, null, null, null, null];
const toWs = []; // mensajes al navegador
function broadcast(obj) { toWs.push({ payload: JSON.stringify(obj) }); }
// Si la pasarela se reinició (redeploy) con navegadores aún conectados,
// se les pide que vuelvan a solicitar la instantánea completa.
if (fresh) broadcast({ type: 'resync' });

// ------------------------------------------------------------------
// A) Restauración desde archivos (al iniciar el flujo)
// ------------------------------------------------------------------
if (msg.topic === 'restore/alarms') {
    const lines = String(msg.payload || '').split('\n').filter(Boolean);
    const restored = [];
    for (const l of lines.slice(-LOG_MAX)) { try { restored.push(JSON.parse(l)); } catch (e) { } }
    G.alarmLog = restored.concat(G.alarmLog).slice(-LOG_MAX);
    context.set('G', G);
    node.warn('Persistencia: ' + restored.length + ' eventos de alarma restaurados');
    out[0] = toWs; return out;
}
if (msg.topic === 'restore/history') {
    const lines = String(msg.payload || '').split('\n').filter(l => l && !l.startsWith('ts'));
    const minT = Date.now() - HIST_MAX_S * 1000;
    const rows = [];
    for (const l of lines) {
        const f = l.split(',');
        const t = Date.parse(f[0]);
        if (!isNaN(t) && t >= minT) rows.push([t, +f[1], +f[2], f[3] === '' ? null : +f[3], +f[4], +f[5], f[6] === '' ? null : +f[6]]);
    }
    G.history = rows.concat(G.history).slice(-HIST_MAX_S);
    context.set('G', G);
    node.warn('Persistencia: ' + rows.length + ' muestras de histórico restauradas');
    broadcast({ type: 'resync' });
    out[0] = toWs; return out;
}

// ------------------------------------------------------------------
// B) Mensajes del navegador (WebSocket)
// ------------------------------------------------------------------
if (msg._session) {
    let req;
    try { req = JSON.parse(msg.payload); } catch (e) { return null; }
    if (req.type === 'hello') {
        // Respuesta solo a ese navegador (se conserva msg._session)
        out[0] = { _session: msg._session, payload: JSON.stringify({
            type: 'snapshot', telemetry: G.telemetry, status: G.status, active: G.active,
            history: G.history, alarmLog: G.alarmLog, ackLog: G.ackLog, comms: G.comms, serverTime: new Date().toISOString() }) };
        return out;
    }
    if (req.type === 'cmd' && req.cmd && req.cmd.action) {
        const cmd = Object.assign({}, req.cmd);
        cmd.cmdId = cmd.cmdId || ('web-' + Date.now().toString(36) + '-' + Math.floor(Math.random() * 1e6));
        cmd.ts = cmd.ts || new Date().toISOString();
        cmd.source = cmd.source || 'dashboard-web';
        G.comms.cmdsSent++;
        context.set('G', G);
        out[1] = { topic: BASE + 'commands', payload: cmd };
        out[4] = { filename: dataDir() + '/eventos.jsonl', payload: JSON.stringify({ dir: 'OUT', topic: BASE + 'commands', at: new Date().toISOString(), msg: cmd }) };
        broadcast({ type: 'cmd_sent', cmd: cmd });
        out[0] = toWs;
        return out;
    }
    return null;
}

// ------------------------------------------------------------------
// C) Mensajes MQTT recibidos desde el broker
// ------------------------------------------------------------------
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { G.comms.parseErrors++; context.set('G', G); node.warn('JSON inválido en ' + msg.topic); return null; }
}
const sub = msg.topic.startsWith(BASE) ? msg.topic.slice(BASE.length) : msg.topic;
G.comms.rx[sub] = (G.comms.rx[sub] || 0) + 1;
G.comms.lastRxAt = new Date().toISOString();

switch (sub) {
    case 'telemetry': {
        if (G.comms.lastSeq !== null && p.seq > G.comms.lastSeq + 1) G.comms.seqGaps += p.seq - G.comms.lastSeq - 1;
        G.comms.lastSeq = p.seq;
        G.comms.latencyMs = Date.now() - Date.parse(p.ts);
        G.telemetry = p;
        broadcast({ type: 'telemetry', data: p, comms: G.comms });
        // Muestreo del histórico a 1 Hz + persistencia CSV
        const t = Date.parse(p.ts), sec = Math.floor(t / 1000);
        if (sec !== G.lastSampleSec) {
            G.lastSampleSec = sec;
            const d = p.data, k = p.kpi || {};
            const row = [t, d.lineSpeed, d.speedSetpoint, d.lastFillLevel, k.unitsPerMin, k.rejectPct, k.availability];
            G.history.push(row);
            if (G.history.length > HIST_MAX_S) G.history.splice(0, G.history.length - HIST_MAX_S);
            out[3] = { filename: dataDir() + '/historico-' + today() + '.csv',
                       payload: [p.ts, d.lineSpeed, d.speedSetpoint, d.lastFillLevel === null ? '' : d.lastFillLevel, k.unitsPerMin, k.rejectPct, k.availability === null ? '' : k.availability, d.lineState, d.bottlesCounted].join(',') };
        }
        break;
    }
    case 'status':
        G.status = p;
        broadcast({ type: 'status', data: p });
        break;
    case 'alarms':
        G.alarmLog.push(p);
        if (G.alarmLog.length > LOG_MAX) G.alarmLog.shift();
        broadcast({ type: 'alarm', data: p });
        out[2] = { filename: dataDir() + '/alarmas.jsonl', payload: JSON.stringify(p) };
        break;
    case 'alarms/active':
        G.active = p;
        broadcast({ type: 'alarms_active', data: p });
        break;
    case 'ack':
        G.ackLog.push(p);
        if (G.ackLog.length > 50) G.ackLog.shift();
        broadcast({ type: 'ack', data: p });
        out[4] = { filename: dataDir() + '/eventos.jsonl', payload: JSON.stringify({ dir: 'IN', topic: msg.topic, at: new Date().toISOString(), msg: p }) };
        break;
}
context.set('G', G);
out[0] = toWs;
node.status({ fill: G.status && G.status.online ? 'green' : 'red', shape: 'dot', text: 'seq ' + G.comms.lastSeq + ' · gaps ' + G.comms.seqGaps + ' · alarmas ' + G.alarmLog.length });
return out;

// =====================================================================
// A07 · LECTURA DE PERSISTENCIA AL ARRANCAR
// Prepara la lectura de los archivos locales (registro de alarmas e
// histórico del día) para que el dashboard no pierda datos al reiniciar.
// Carpeta: variable de entorno A07_DATA_DIR o ~/.node-red/a07-data
// =====================================================================
const dir = env.get('A07_DATA_DIR') || ((env.get('HOME') || env.get('USERPROFILE') || '.') + '/.node-red/a07-data');
const d = new Date();
const today = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
node.status({ fill: 'blue', shape: 'dot', text: dir });
return [[
    { topic: 'restore/alarms', filename: dir + '/alarmas.jsonl' },
    { topic: 'restore/history', filename: dir + '/historico-' + today + '.csv' }
]];

// Primer arranque: el archivo aún no existe. No es un error de operación.
// Si es el histórico del día, se crea con su fila de encabezado.
const f = (msg.filename || '') + '';
node.status({ fill: 'grey', shape: 'ring', text: 'sin archivo previo: ' + f.split('/').pop() });
if (f.indexOf('historico-') >= 0) {
    return { filename: f, payload: 'ts,lineSpeed_envmin,speedSetpoint_envmin,lastFillLevel_pct,unitsPerMin,rejectPct,availabilityPct,lineState,bottlesCounted' };
}
return null;
